//! R10 deterministic capacity ladder + binary search gate; review only.
use serde_json::json;
use std::collections::BTreeMap;
fn vw(l:&[(f64,f64)],q:f64)->Option<f64>{let(mut x,mut t)=(q,0.);for&(p,a)in l{let z=x.min(a);t+=z*p;x-=z;if x<=q*1e-9{return Some(t/q)}}None}
fn sample(a:&[(f64,f64)],b:&[(f64,f64)],q:f64,cost:f64,thr:f64)->Option<f64>{let x=vw(a,q)?;let y=vw(b,q)?;if(y/x-1.)*10000.-cost>=thr{Some((x*q).max(y*q))}else{None}}
fn check(t:&mut BTreeMap<u64,Option<f64>>,u:u64,a:&[(f64,f64)],b:&[(f64,f64)],step:f64,cost:f64,thr:f64)->Option<f64>{if let Some(v)=t.get(&u){return *v}let v=sample(a,b,u as f64*step,cost,thr);t.insert(u,v);v}
fn cap(a:&[(f64,f64)],b:&[(f64,f64)],step:f64,minq:f64,maxq:Option<f64>,cost:f64,thr:f64)->(f64,bool,usize){let price=a[0].0.max(b[0].0);let first=(minq/step).round()as u64;let research=((500./price)/step+1e-9).floor()as u64;let mut last=research.max(first);if let Some(m)=maxq{last=last.min((m/step+1e-9).floor()as u64)}let mut best=first;let mut t=BTreeMap::new();check(&mut t,first,a,b,step,cost,thr);for usd in[10.,25.,50.,100.,200.,500.]{let u=last.min(((usd/price)/step+1e-9).floor()as u64);if u>=first&&check(&mut t,u,a,b,step,cost,thr).is_some(){best=best.max(u)}}if check(&mut t,last,a,b,step,cost,thr).is_some(){best=best.max(last)}let mut high=t.iter().filter(|(u,v)|**u>best&&v.is_none()).map(|(u,_)|*u).min().unwrap_or(last+1);for _ in 0..12{if high-best<=1{break}let m=(best+high)/2;if check(&mut t,m,a,b,step,cost,thr).is_some(){best=m}else{high=m}}let val=check(&mut t,best,a,b,step,cost,thr).unwrap_or(0.);let proven=best==last&&last==research&&val>=500.-price*step-1e-6;((val.min(500.)*100.).round()/100.,proven,t.len())}
fn main(){let cases=[("ceiling",vec![(100.,100.)],vec![(101.,100.)],0.001,0.001,None,500.0,true),("depth200",vec![(100.,2.)],vec![(101.,2.)],0.001,0.001,None,202.0,false),("max100",vec![(100.,100.)],vec![(101.,100.)],0.001,0.001,Some(1.0),101.0,false),("edgefail",vec![(100.,100.)],vec![(100.5,100.)],0.001,0.001,None,0.0,false)];let mut f=vec![];for(n,a,b,s,m,x,w,p)in cases{let(v,pr,t)=cap(&a,&b,s,m,x,20.,42.);if(v-w).abs()>1.1||pr!=p{f.push(json!({"case":n,"value":v,"proven":pr,"tests":t,"want":w}))}}println!("{}",json!({"r10_capacity_gate":f.is_empty(),"cases":4,"failures":f,"trading":false}));}